@layer base {
  * {
    @apply border-border font-medium;
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: smooth;
    font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif);
