              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {regions.map((region, row) => (
            <tr className="border-t" key={region}>
              <td className="px-3 py-2">{region}</td>
              {months.map((month, column) => (
                <td className="px-3 py-2 text-end tabular-nums" key={month}>
                  {((row + 3) * (column + 7) * 37) % 900}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </ScrollArea>
  )
}
