        animate={content.animate}
        transition={content.transition}
        className={cn('size-full', className)}>
        <ResizablePrimitive.Group
          className={cn('flex size-full')}
          data-slot="panel-group"
          dir={direction}
          elementRef={ref}
          {...props}
        />
      </m.div>
    </LazyMotion>
  )
})
