        </MotionAccordionContent>
      </MotionAccordionItem>
      <MotionAccordionItem value="item-3">
        <MotionAccordionTrigger>Is it animated?</MotionAccordionTrigger>
        <MotionAccordionContent>
          Yes. It&apos;s animated by default, but you can disable it if you prefer.
        </MotionAccordionContent>
      </MotionAccordionItem>
    </MotionAccordion>
  )
}
