import { Button } from '~/components/button'
import { CommandShortcut } from '~/components/command'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '~/components/tooltip'
import { ArrowBigUpDash, Command } from 'lucide-react'
import React from 'react'
import { toast } from 'sonner'

export function Demo() {
  const [open, setOpen] = React.useState<boolean>(false)

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            aria-expanded={open}
            aria-label={'advanced button'}
            icon={<ArrowBigUpDash />}
            isCollapsed={open}
            loading={false}
            onClick={() => setOpen((prev) => !prev)}
            size="default">
            Button
          </Button>
        </TooltipTrigger>
        <TooltipContent forceMount side="top" className="flex items-center gap-2">
          <CommandShortcut
            keys="mod+i"
            onKeysPressed={() => {
              setOpen((prev) => !prev)
              toast.success('Advanced button')
            }}
            variant="secondary">
            <Command />
            +i
          </CommandShortcut>
          <p>Advanced button</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}
