        initial={isHorizontal ? MOTION_SEPARATOR_INITIAL_HORIZONTAL : MOTION_SEPARATOR_INITIAL_VERTICAL}
        animate={MOTION_SEPARATOR_ANIMATE}
        transition={springBouncy}
        data-slot="separator"
        {...props}
      />
    </LazyMotion>
  )
})
MotionSeparator.displayName = 'MotionSeparator'

