      adapter,
      mode,
      locale: { locale, weekStartDay, direction },
      month: controlledMonth,
      defaultMonth,
      selected,
      onSelect: onSelect ? (value) => callCalendarSelectHandler(mode, onSelect, value) : undefined,
      onMonthChange,
      showOutsideDays,
      fixedWeeks,
      numberOfMonths,
      disabled,
      fromDate,
      toDate,
      onDismiss,
      pageBehavior,
      unavailable,
      readOnly,
      invalid,
    })

