export function Demo() {
  const [dark, setDark] = React.useState(false)

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-2">
        <Switch
          checked={dark}
          checkedIndicator={<Moon />}
          id="theme-switch"
          indicator={<Sun />}
          onCheckedChange={setDark}
